            val plan =
                EmitPlan(
                    writtenFiles =
                        listOf(
                            Path(".opencode/command/foo/SKILL.md"),
                        ),
                    deletedFiles = emptyList(),
                    externalCommands = emptyList(),
                    warnings = emptyList(),
